45	@Slf4j
46	@Service
47	@RequiredArgsConstructor
48	public class BasicMqttClientAuthProvider implements MqttClientAuthProvider {
49	
50	    private final AuthorizationRuleService authorizationRuleService;
51	    private final MqttClientCredentialsService clientCredentialsService;
52	    private final CacheNameResolver cacheNameResolver;
53	    private BCryptPasswordEncoder passwordEncoder;
54	    private HashFunction hashFunction;
55	
56	    @Autowired
57	    public BasicMqttClientAuthProvider(AuthorizationRuleService authorizationRuleService,
58	                                       MqttClientCredentialsService clientCredentialsService,
59	                                       CacheNameResolver cacheNameResolver,
60	                                       @Lazy BCryptPasswordEncoder passwordEncoder) {
61	        this.authorizationRuleService = authorizationRuleService;
62	        this.clientCredentialsService = clientCredentialsService;
63	        this.cacheNameResolver = cacheNameResolver;
64	        this.passwordEncoder = passwordEncoder;
65	        this.hashFunction = Hashing.sha256();
66	    }
67	
68	    @Override
69	    public AuthResponse authenticate(AuthContext authContext) throws AuthenticationException {
70	        if (log.isTraceEnabled()) {
71	            log.trace("[{}] Authenticating client with basic credentials", authContext.getClientId());
72	        }
73	        MqttClientCredentials basicCredentials = authWithBasicCredentials(authContext.getClientId(), authContext.getUsername(), authContext.getPasswordBytes());
74	        if (basicCredentials == null) {
75	            log.error("Failed to authenticate client with Basic credentials matching clientId: [{}] username: [{}]", authContext.getClientId(), authContext.getUsername());
76	            return new AuthResponse(false, null, null);
77	        }
78	        if (log.isTraceEnabled()) {
79	            log.trace("[{}] Authenticated as {} with username {}", authContext.getClientId(), basicCredentials.getClientType(), authContext.getUsername());
80	        }
81	        BasicMqttCredentials credentials = JacksonUtil.fromString(basicCredentials.getCredentialsValue(), BasicMqttCredentials.class);
82	        AuthRulePatterns authRulePatterns = authorizationRuleService.parseBasicAuthorizationRule(credentials);
83	        return new AuthResponse(true, basicCredentials.getClientType(), Collections.singletonList(authRulePatterns));
84	    }
85	
86	    private MqttClientCredentials authWithBasicCredentials(String clientId, String username, byte[] passwordBytes) {
87	        List<String> credentialIds = getCredentialIds(clientId, username);
88	        List<MqttClientCredentials> matchingCredentialsList = clientCredentialsService.findMatchingCredentials(credentialIds);
89	        if (log.isDebugEnabled()) {
90	            log.debug("Found credentials {} for credentialIds {}", matchingCredentialsList, credentialIds);
91	        }
92	        String password = passwordBytesToString(passwordBytes);
93	        if (password != null) {
94	            MqttClientCredentials credentialsFromCache = getBasicCredsPwCache().get(toHashString(password), MqttClientCredentials.class);
95	            if (credentialsFromCache != null && matchingCredentialsList.contains(credentialsFromCache)) {
96	                return credentialsFromCache;
97	            }
98	        }
99	
100	        for (MqttClientCredentials credentials : matchingCredentialsList) {
101	            BasicMqttCredentials basicMqttCredentials = MqttClientCredentialsUtil.getMqttCredentials(credentials, BasicMqttCredentials.class);
102	            if (isMatchingPassword(password, basicMqttCredentials)) {
103	                if (password != null && basicMqttCredentials.getPassword() != null) {
104	                    getBasicCredsPwCache().put(toHashString(password), credentials);
105	                }
106	                return credentials;
107	            }
108	        }
109	        return null;
110	    }
111	
112	    private List<String> getCredentialIds(String clientId, String username) {
113	        List<String> credentialIds = new ArrayList<>();
114	        if (!StringUtils.isEmpty(username)) {
115	            credentialIds.add(ProtocolUtil.usernameCredentialsId(username));
116	        }
117	        if (!StringUtils.isEmpty(clientId)) {
118	            credentialIds.add(ProtocolUtil.clientIdCredentialsId(clientId));
119	        }
120	        if (!StringUtils.isEmpty(username) && !StringUtils.isEmpty(clientId)) {
121	            credentialIds.add(ProtocolUtil.mixedCredentialsId(username, clientId));
122	        }
123	        return credentialIds;
124	    }
125	
126	    private boolean isMatchingPassword(String password, BasicMqttCredentials basicMqttCredentials) {
127	        return basicMqttCredentials.getPassword() == null
128	                || (password != null && passwordEncoder.matches(password, basicMqttCredentials.getPassword()));
129	    }
130	
131	    private String passwordBytesToString(byte[] passwordBytes) {
132	        return passwordBytes != null ? new String(passwordBytes, StandardCharsets.UTF_8) : null;
133	    }
134	
135	    private Cache getBasicCredsPwCache() {
136	        return cacheNameResolver.getCache(CacheConstants.BASIC_CREDENTIALS_PASSWORD_CACHE);
137	    }
138	
139	    private String toHashString(String rawPassword) {
140	        return hashFunction.newHasher().putString(rawPassword, StandardCharsets.UTF_8).hash().toString();
141	    }
142	}
